def transform(grid):
    row=grid[0]; w=len(row); c=row.index(2)
    out=[[0]*w for _ in range(w)]
    m=min(c,w-1-c)
    for r in range(m+1):
        out[r][c-r]=2; out[r][c+r]=2
    k=0
    while True:
        d=c-4-4*k
        rr=(c-d)//2+1; cc=(c+d)//2+1
        while cc<0 or rr<0: rr+=1; cc+=1
        if rr>w-1 or cc>w-1: break
        r,co=rr,cc
        while r<=w-1 and co<=w-1:
            out[r][co]=1; r+=1; co+=1
        k+=1
    return out
